import{_ as a,C as r,o,c as n,j as p,a as l,E as s,a6 as i}from"./chunks/framework.CnPv4DE1.js";const b=JSON.parse('{"title":"创造新生活的最快方式(一份12个月计划)","description":"","frontmatter":{"title":"创造新生活的最快方式(一份12个月计划)","originalTitle":"The Fastest Way Create A New Life (A 12 Month Plan)","date":"2025-01-04","originalUrl":"https://thedankoe.com/letters/the-fastest-way-create-a-new-life-a-12-month-plan/","minutes":12,"sourceHash":"7c5c9c884272c38cae38dc34825e9f512711ba7f645a475e71f4e78b29e4ac36","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-fastest-way-create-a-new-life-a-12-month-plan/"}]]},"headers":[],"relativePath":"letters/the-fastest-way-create-a-new-life-a-12-month-plan.md","filePath":"letters/the-fastest-way-create-a-new-life-a-12-month-plan.md"}'),h={name:"letters/the-fastest-way-create-a-new-life-a-12-month-plan.md"};function m(c,e,u,d,f,q){const t=r("ArticleMeta");return o(),n("div",null,[e[0]||(e[0]=p("h1",{id:"创造新生活的最快方式-一份12个月计划",tabindex:"-1"},[l("创造新生活的最快方式(一份12个月计划) "),p("a",{class:"header-anchor",href:"#创造新生活的最快方式-一份12个月计划","aria-label":'Permalink to "创造新生活的最快方式(一份12个月计划)"'},"​")],-1)),s(t),e[1]||(e[1]=i('<p><a href="https://www.youtube.com/embed/Lt79hNo6SWE?si=2TP-4Um9x3C1CYnE" target="_blank" rel="noreferrer">观看原文视频</a></p><p>毁掉你人生最快的方式,就是遵循别人的计划。</p><p>但问题是:</p><p>心智渴望秩序。</p><p>在没有<em>思考</em>的情况下,我们会寻求安全、稳妥和舒适。</p><p>当我年轻、懵懂,学着在这个世界上生存时,我的命运掌握在父母手中。我太年轻了,无法信任自己的思考,所以我被设定的那条路,就是我唯一知道的路。</p><p>这就是事情开始出错的地方。</p><p>我们都知道,风险最小的路径其实是所有路径中风险最大的。我们都知道,舒适的生活是这世上最不舒适的事情。于是我们陷入了一个循环:寻求舒适、变得不适、寻求更多舒适、变得更加不适,最终,你会陷入一个深坑,想要爬出来变得异常艰难。如果生活如此舒适,你为什么还需要用即时的快感来麻痹痛苦?</p><p>但事情是这样的。</p><p>这并不像设定一个新目标那么简单。</p><p>尤其如果那是一个新年愿望,而你之所以定下它只是因为别人都在定。你的目标之下没有堆叠一整座“为什么”的冰山,所以放弃追求它们轻而易举。</p><p>你以前就这样做过。那个华丽的新目标能让你振奋几个小时,但随后你又发现自己回到了原本想逃离的那片分心的云雾之中。</p><p>如果你想避免过一种机械化、被预先设定好的人生,解决之道就是<em>为你的心智配备正确的工具,让你能够独立思考。</em></p><p>以下是开始的方法(这段旅程可能会很痛苦):</p><h2 id="你需要一个计划-但不是大多数计划那种" tabindex="-1">你需要一个计划,但不是大多数计划那种 <a class="header-anchor" href="#你需要一个计划-但不是大多数计划那种" aria-label="Permalink to &quot;你需要一个计划,但不是大多数计划那种&quot;">​</a></h2><blockquote><p>你瞄准什么,决定了你能看到什么。——乔丹·彼得森(Jordan Peterson)</p></blockquote><p>你需要一个计划。</p><p>没有别的办法。</p><p>因为如果你没有计划,社会就会替你安排,而他们已经为你的人生规划了几十年。</p><p>计划不是一份不会实现的事项清单。它是一份不断演进的蓝图,用以塑造你的心智,使其能够察觉那些能带来进步的想法。</p><p>问题在于,人们顺从了父母或社会设定的目标,然后就止步于此。他们知道拥有一个目标是好事,但并不真正理解目标<em>是什么</em>。大多数人追求目标是为了获得认可和地位,而不是为了那种源自克服阻力而产生的快乐。</p><p>为什么这是个问题?因为构成你心智、身份和视角的那些目标——通常按这个顺序,像一组同心圆——过滤着你所感知到的一切。</p><p>一个以上学找工作为目标的人,不会注意到创业、追求自己人生事业的机会。一个以创业为目标的人,也不会注意到那些能帮他取得好成绩的想法。</p><p>在这两种情况下,每个人都可能读同一本书(或读这篇文章),却带着截然不同的收获,去决定如何运用这些信息。</p><p>关键在于,我们不想要顺从。我们想要创造力。我们想要与众不同。我们想要独一无二。我们想要创造<em>自己的</em>人生,而不是活别人的人生。我们想要<em>新的</em>发现,而不是复制上一代人的旧结果,因为如果你看看周围,大多数人都没有拥有任何接近你想要的未来的东西。</p><h3 id="计划是你发现新事物的表面积" tabindex="-1">计划是你发现新事物的表面积 <a class="header-anchor" href="#计划是你发现新事物的表面积" aria-label="Permalink to &quot;计划是你发现新事物的表面积&quot;">​</a></h3><p>先把一件事说清楚:</p><p>要实现你人生中想要的任何东西(在现实允许的范围内),都存在一套操作顺序。</p><p>想想这个简单的方程:4 + 6 x (5 + 3 – 2) = ?</p><p>这个方程的答案,就是你想要实现的目标。</p><p>方程本身,就是你要解决的问题。</p><p>要解决这个问题、实现这个目标,你需要按<em>特定的</em>顺序进行加、减、乘运算。如果顺序错了,你就得不出正确的答案。</p><p>但这就是生活。</p><p>你没有那个方程。</p><p>你甚至不知道答案。</p><p>你所拥有的,只是对你想要的答案的一种猜测,以及通过实验和纠错来创造方程、也就是知识的能力。这个方程对你自己和他人都是有价值的。它是一种可以呈现多种形式的具体知识。有时,这个方程是一款产品或服务,一本书,或是你给孩子的建议,以推动人类的进步。如果快乐来自于克服阻力,以及与某种比自身更宏大之物的联系,那么创造力就是承载这两者的载体。这就是我为什么写作。</p><p>所以这就是我们的起点。</p><p>一个目标,或一个问题。</p><p>两者相依而生,缺一不可。</p><p>但大多数人不知道自己想追求什么目标。或者他们的心智已经被预设的目标编程,这使得他们极难察觉到问题。派对、睡懒觉,以及所有其他坏习惯,都不算问题,除非它们阻碍你实现目标。既然那条既定路径的目标只是上学、找工作、65岁退休,这些并不需要太多努力或创造力,所以你完全可以做个混日子的人。</p><p>最好的起点,是对自己当下的处境完全诚实。</p><p>你对自己的生活满意吗?</p><p>这是个陷阱问题。</p><p>没有人是满意的。</p><p>让我看看谁能每一秒都感到快乐,我就能证明他在说谎。生活是波浪式的。是循环往复的。有高潮也有低谷。这是刻在现实本质里的东西。如果没有低谷,就不会有创造力,也就不会有我们今天所知的这种生活。</p><p>在这其中,潜藏着无穷多的问题,而它们正是决定你生活质量的源头。</p><p>选一个。</p><p>从那里开始。</p><p>别问我该选哪个。</p><p>你<em>自己知道</em>该选哪个。</p><p>但现在事情开始变得可怕了。未知在逼近。你已经站在水里,水深及膝,想要冲回岸上。关于那个问题的念头开始不断增殖,因为你的心智已经失去了所有的约束和边界。</p><p>这被称为心理熵,也就是<em>心智中的无序状态</em>。仅仅一个关于你这周新增体重的念头,就很容易分裂成上千个想法:朋友们会怎么想,你不穿上衣时会是什么样子,你会不会孤独终老。</p><p>在问题和目标之间,存在着制定计划的机会。一种策略。一套目标的层级结构,能在你踏入未知领域时为你的心智搭建框架,把混乱挡在门外。这是发现新事物的表面积。</p><p>但你要如何制定计划呢?</p><p>你要如何阻止四壁向你压来?</p><h2 id="如何在未知中航行-并创造你想要的生活" tabindex="-1">如何在未知中航行(并创造你想要的生活) <a class="header-anchor" href="#如何在未知中航行-并创造你想要的生活" aria-label="Permalink to &quot;如何在未知中航行(并创造你想要的生活)&quot;">​</a></h2><p>这将是一个痛苦的过程。</p><p>你不只是在创造一种新生活。你是在创造一个新的身份。你在扩展自己的心智,使其能容纳更多的复杂性,从而让你能够解决更有价值的问题。</p><p>这不像设定一个目标或制定一个新年愿望那么简单,因为你还不是那个能够实现那些目标的人。</p><p>你还没有那种能够实现那些目标的<em>身份</em>。</p><p>健美运动员在饮食、训练和恢复方面毫无问题。他们的整个<em>生活</em>都围绕着他们的目标运转。每一个决定都是投给未来的一票。作家在产生想法或发表作品方面毫无问题。而另一方面,游戏玩家一次盯着屏幕八个小时也毫无问题,无论这好还是不好。</p><p>并不是你没有自律。你在吃喝、参加派对、熬夜晚睡,以及把让大脑变迷糊的Totino’s披萨卷当作午后零食这些事上毫无问题(因为这些并不与你身份的目标相冲突)。而健美运动员如果得不到他愿景所需的那种食物,则会陷入深深的混乱。自律是身份的一种特征。当你试图成为一个新的人时,<em>你现在是谁</em>正在与<em>你想成为谁</em>相互对抗,这个过程是痛苦的。你会经历一段成长的阵痛期,直到你的新身份逐渐固化下来。</p><p>我们需要逐步推进这个过程。</p><h3 id="_1-创造你自己的小世界" tabindex="-1">1) 创造你自己的小世界 <a class="header-anchor" href="#_1-创造你自己的小世界" aria-label="Permalink to &quot;1) 创造你自己的小世界&quot;">​</a></h3><p>我认识的最成功的人,都活在他们自己的小世界里。</p><p>他们编写了属于自己的电子游戏。</p><p>它令人上瘾。它令人愉悦。它提供了一套能带来经验积累的逻辑步骤序列。它帮助他们理解什么值得关注、什么值得学习。它是一个能够抵御干扰、约束熵增的心智框架。</p><p>你要先为自己的新身份打下基础,才能开始构建你的世界。</p><p>我们需要面面俱到。我们需要创造一个完整的闭环,作为你的参照框架。我们需要一副透镜,用来观察生活、察觉新机会、做出更好的决策,并感知我们何时偏离了方向,以便我们能朝更好的方向纠正错误。</p><p>别指望这一切会一蹴而就。你的心智花了几十年才形成了现在的样子。它也需要一些时间,才能塑造成你为它提供的这个不断扩展的模具。</p><p>把这些写下来:</p><ul><li><strong>反愿景</strong>。你所厌恶的那种生活的画面。</li><li><strong>愿景</strong>。你理想未来的画面。</li><li><strong>约束条件</strong>。为实现愿景,你不愿意牺牲的东西。</li><li><strong>十年目标</strong>。十年后你想达到的位置。</li><li><strong>一年目标</strong>。一年后你想达到的位置。</li></ul><p>如果你想要一份用于此的练习表,<a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">点这里。</a></p><p>记住,目标只是一个瞄准点或期望的结果。仅此而已。目标可以,也应该,在接触到更好的信息时不断演变。目标不是未来某个必须不惜一切代价去实现的静止之点。目标是用来识别问题的工具。问题需要解决方案。解决方案必须通过创造性的猜测和纠错才能得出。目标是<em>视角</em>,必须持续不断地被打磨。</p><p>通过这些,你正在为你计划要写的那个故事创建<em>大纲</em>。</p><p>当你写一个故事时,你不会坐下来直接开始写。你会先创建一个结构,让你的心智借此浮现出想法,并影响你对对话、信息和内心独白的感知。</p><p>从那里出发,你不断添加、删减、重新排序,并打磨这些想法,直到你有足够的清晰度去写出初稿。</p><p>问题是,生活不是一本书或一场会终结的游戏。没有最终的目标。唯一真正的目标,就是继续玩下去。</p><p>你要如何开始朝这些目标取得进展呢?</p><p>项目。</p><h3 id="_2-把能量投入到一系列项目中" tabindex="-1">2) 把能量投入到一系列项目中 <a class="header-anchor" href="#_2-把能量投入到一系列项目中" aria-label="Permalink to &quot;2) 把能量投入到一系列项目中&quot;">​</a></h3><p>别去学技能。</p><p>去做项目。</p><p>技能,和学位一样,孤立存在时几乎毫无用处。</p><p>一系列的项目,才是你走向理想生活的方式。如果你想要有所得,你必须先付出,而把知识只留在脑子里,是让你对自己有多聪明、别人却多不在乎这件事变得愤懑不平的必然之路。</p><p>一个项目就是你游戏中的一个任务。你构建得越多,你在自己的特质、职业、角色和能力上投入的经验就越多。当你构建一个项目时,你会学到相关的<em>技巧</em>,让你能够解决一个问题、实现一个具体的结果。</p><p>但项目一开始并不具有意义。随着你为其投入能量,它才会变得有意义。这也起到了一个过滤器的作用,能筛掉那些无法克服“别人会怎么想”这种恐惧的人。</p><p>一个意义不断增加的项目,由问题、理想结果、里程碑、杠杆点、任务,以及基于兴趣的学习所构成。</p><p>你的项目必须解决源自你的反愿景的问题,并孕育出能够构建你愿景的解决方案。</p><p>如果你在钱上挣扎,那就是一个问题。从这里出发,你就能构想出一个<strong>项目</strong>,与&quot;拥有一个成功的企业&quot;这一愿景示例保持一致,同时受到&quot;每天只工作4小时,以便有时间陪伴家人或经营关系&quot;这一<strong>约束</strong>的限制。这会大幅缩小你能构建的项目类型。</p><p>如果你不在正确的环境中,你根本不会注意到这是一个选项。但如果你对现代商业模式这类东西有所了解,你就会看到<a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">一人企业</a>是一个可行的选项。</p><p>从这里出发,你创建一个项目,比如开始做一份newsletter(邮件订阅)。你不会陷入&quot;教程地狱&quot;,一直学习关于newsletter的东西。你直接开始。你去搜索一些<em>技巧</em>,比如如何选择主题、如何写标题。你继续积累技巧,比如如何构建有说服力的文章结构。不知不觉间,你就拥有了&quot;写newsletter&quot;这项技能,但这种方式不是那种能在类似情境下被线性传授的技能。你离变得不可替代又近了一步。然后,当你发现问题——比如你的newsletter没有增长,或者没有带来任何收入——你就转向下一个项目。</p><p>再说一次,项目就像目标一样。它们随时间演变,不是静止不变的。别再为此担心了。</p><h3 id="_3-搜寻一堆理由" tabindex="-1">3) 搜寻一堆理由 <a class="header-anchor" href="#_3-搜寻一堆理由" aria-label="Permalink to &quot;3) 搜寻一堆理由&quot;">​</a></h3><p>曾有几个重大的时刻永久地改变了我的人生。</p><p>通常是从我意识到自己已经变得停滞不前开始的。我讨厌那种感觉。仅仅这个意识本身,就让我想去寻找<em>理由</em>把自己挖出来。</p><p>你要知道,你的大脑被设定为要为生存而狩猎。但人类是在概念层面上生存的。我们能从身体上的威胁中注意到的心理反应,和我们能从概念上的威胁中注意到的心理反应,是一样的。这是对你身份认同的威胁。</p><p>由于目标构成了你的身份认同,一个健美运动员如果被打乱了训练计划,就会<em>感觉</em>到痛苦。他们并没有面临任何真实的威胁,但那种<em>感觉</em>就像是有威胁一样,因为他们的身份认同因为无法朝目标取得进展而受到了威胁。</p><p>多巴胺会在某件事对我们的生存很重要时发出信号。我们会记住那些信息,因为它将来会有用。</p><p>当你在追求想要的生活的过程中重新塑造自己时,你的思维会开始改变。你会感受到那种张力——继续保持那些阻碍你的习惯所带来的张力。</p><p>把这当作一个机会,主动去搜寻<em>理由</em>来做出改变。</p><p>读新书。摄取新信息。去寻找一个理由让自己坚持你正在做的事,而不是反过来。</p><p>人们在开始后两周就放弃,这太常见了。他们的大脑在搜寻放弃的理由。你需要做相反的事。去搜寻继续下去的理由。这可以很简单,就是在谷歌里输入&quot;我为什么应该创业?&quot;或&quot;我为什么应该去健身房?&quot;,然后让你的好奇心接管接下来的一切。</p><p>让&quot;不改变&quot;这件事变得很难做到。</p><h3 id="_4-记录你的人生" tabindex="-1">4) 记录你的人生 <a class="header-anchor" href="#_4-记录你的人生" aria-label="Permalink to &quot;4) 记录你的人生&quot;">​</a></h3><blockquote><p><strong>门徒效应(protégé effect)</strong>——一个学习方面的概念,认为我们通过向他人传授信息来更有效地学习,即便那些他人并不一定比我们知道得少。</p></blockquote><p>在伟大的古代社会中,像马可·奥勒留(Marcus Aurelius)这样属于上层阶级的人,能够接触到当时最好的老师。</p><p>如今,我们拥有的东西甚至更好。</p><p>那就是<em>互联网</em>。</p><p>你只需点击一个按钮,就能接触到世界上大多数最伟大的思想者。你可以读他们的书,看他们的视频,追踪他们的作品。如果你愿意,你甚至可以给他们发邮件、发消息,或者请他们上播客。</p><p>但这个全新数字世界带来的好处远不止于此。</p><p>你的项目一旦建成,你会拿它们来做什么?</p><p>你只是把它们扔进一个&quot;作品集&quot;,在合适的时机拿给潜在雇主看吗?</p><p>还是说,你踏上这条路的初衷,是想做出一些独特的东西?</p><p>在互联网上,你不需要许可就能发表你的作品。</p><p>不仅如此,你也不需要许可就能分享你所知道的东西。</p><p>在我看来,大幅提高你成功几率的最好方法,就是把你的旅程记录下来,让任何人都能发现它。</p><p>成为一个创作者。不是内容创作者,而是那种利用内容等资源来传播自己作品的创作者。</p><p>分享你的想法、观点、问题、愿景,以及在通向目标过程中所学到的东西。</p><p>把你的项目变成产品,并测试它们的价值。</p><p>当你把自己的创作以帖子和产品的形式公开发布时,你不需要去质疑它们是否有价值。市场会告诉你答案。</p><p>如果它们很烂——一开始它们肯定会很烂——那很好。你已经发现了一个问题,而如果你悄悄地默默进展,你根本不可能发现它。</p><p>我可以就这个话题写整整一封信,而且之前我已经写过很多次了,或者我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>里教你如何开始,所以我就在这里结束,把这个想法留给你,在你度过这一天的时候好好想一想。</p><p>感谢阅读。</p><p>——Dan</p><hr><p><a href="/en/letters/the-fastest-way-create-a-new-life-a-12-month-plan">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',127))])}const g=a(h,[["render",m]]);export{b as __pageData,g as default};
